# Реестр вопросов на решение команды (юрист / аналитик / руководитель)
import json, os
from openpyxl import Workbook
from openpyxl.styles import Font, Alignment, PatternFill
from openpyxl.utils import get_column_letter
from openpyxl.worksheet.datavalidation import DataValidation
TYPES={'займ':'Займ','залог':'Залог','гарантия':'Гарантия','поручение':'Поручение','дкп':'ДКП (лизинг)','лизинг':'Финансовый лизинг'}
FILES={'займ':'02_сравнение_займ.xlsx','залог':'02_сравнение_залог.xlsx','гарантия':'02_сравнение_гарантия.xlsx','поручение':'02_сравнение_поручение.xlsx','дкп':'02_сравнение_ДКП_лизинг.xlsx','лизинг':'02_сравнение_финансовый_лизинг.xlsx'}
Q=[]
def add(stage,typ,topic,question,where,who): Q.append([stage,typ,topic,question,where,who])
# Этап 1 — спорные случаи классификации (из сводки этапа 1)
S1=[
 ('Гарантия','Квалификация договора','Документы названы «договор гарантии», но по тексту это солидарное поручительство (Актобе, Алматы, Атырау, Жамбыл, СКО и др.). Считать гарантией или поручительством?','01_реестр.xlsx; 02_сравнение_гарантия.xlsx, лист «Внутренние противоречия»','Юрист'),
 ('Займ','Роли сторон (Атырау)','В займе Атырау «Кредитор» — только агент, ГУ-займодатель стороной не является (основание — приказ №272). Допустима ли такая модель сторон в едином договоре?','01_реестр.xlsx; 02_сравнение_займ.xlsx, строка «Стороны и роли»','Юрист, руководитель'),
 ('Займ','Пункты про ИП в займе СПК (Караганда)','В займе СПК Караганды есть пункты про ИП (6.2.12–6.2.14). Остаток другой формы или намеренно?','01_реестр.xlsx','Аналитик'),
 ('Составные файлы','Туркестан «залог, ДПМ и гарантия»; ЗКО «Приложения Договора»','Составные файлы содержат несколько договоров; в ЗКО нет самого договора поручения. Какие части считать действующими шаблонами?','01_реестр.xlsx','Аналитик, руководитель'),
 ('Поручение','Статус приложений к договору поручения','Считать приложения (перечни документов, требования к залогу, формы отчётности, акт) отдельной группой или частью договора поручения? Сейчас метка «СОМНЕВАЕМСЯ».','01_реестр.xlsx; 02_сравнение_поручение.xlsx, лист «Приложения (СОМНЕВАЕМСЯ)»','Юрист, руководитель'),
 ('Все','Заполненные экземпляры','Файлы Абая (гарантия по другой программе, займ, залог), Акмолы, Жетісу, Костаная (Прил. 16), Туркестана содержат данные реальных сделок. Подтвердить, что они используются только как образцы структуры.','01_реестр.xlsx','Аналитик'),
 ('Залог','Остатки прежних форм','В залогах Актобе, Алматы, Абая, Жетісу, СКО и ВКО остался абзац «09 декабря 2013 г.»; залог ВКО выгружен из 1С с машинными полями. Удалять при унификации?','02_сравнение_залог.xlsx, лист «Остатки чужих данных»','Юрист'),
]
for t,topic,q,where,who in S1: add('Этап 1',t,topic,q,where,who)
# Этап 2 — пограничные случаи квалификации
S2=[
 ('Займ','График и порядок погашения (очерёдность списания)','Аналитик записал разный порядок очерёдности как противоречие; по определению заказчика это может быть различие значений одного параметра. Как квалифицировать и какой порядок принять?','02_сравнение_займ.xlsx, строка «График и порядок погашения»','Юрист'),
 ('Займ, залог','Способ обращения взыскания на залог','ВКО (займ №19 п. 7.4; залог №18 п. 2.3, №17 п. 2.5) — только судебный порядок в РУССКОМ тексте; в казахском тексте тех же залогов №17 и №18 — «сот және соттан тыс» (судебный и внесудебный), т.е. это также расхождение каз./рус. внутри договора. Остальные регионы — внесудебный и/или судебный. Какой порядок принять?','02_сравнение_займ.xlsx и 02_сравнение_залог.xlsx','Юрист'),
 ('Займ','Заявление после просрочки: право или обязанность','Ұлытау (№53, ст. 4, п. 1 пп. 5)) — обязанность заёмщика; в других регионах (п. 6.1.6) — право. Записано как различие.','02_сравнение_займ.xlsx, строка «Изменение условий/реструктуризация»','Юрист'),
]
for t,topic,q,where,who in S2: add('Этап 2',t,topic,q,where,who)
# Этап 2 — противоречия между договорами (все строки со столбцом «противоречия» ≠ «не выявлено»)
for k,name in TYPES.items():
    d=json.load(open(f's3_input_{k}.json'))
    for r in d['rows']:
        p=r['противоречия'].strip()
        if p and not p.lower().startswith('не выявлен'):
            add('Этап 2',name,r['row'],p,f"{FILES[k]}, строка «{r['row']}»",'Юрист')
# Этап 3 — конфликты, добавляемые после унификации
if os.path.exists('s3_questions.json'):
    for x in json.load(open('s3_questions.json')): add('Этап 3',x['type'],x['topic'],x['question'],x['where'],x.get('who','Юрист, руководитель'))
wb=Workbook(); ws=wb.active; ws.title='Вопросы на решение'
hdr=['№','Этап','Тип договора','Условие / тема','Вопрос и варианты (со ссылками)','Где смотреть','Кто решает (предложение)','Решение','Ответственный','Статус','Комментарий']
ws.append(hdr)
for i,q in enumerate(Q,1): ws.append([i]+q+['','','Открыт',''])
for c in ws[1]: c.font=Font(bold=True); c.fill=PatternFill('solid',fgColor='D9E1F2'); c.alignment=Alignment(wrap_text=True,vertical='top')
for row in ws.iter_rows(min_row=2):
    for c in row: c.alignment=Alignment(wrap_text=True,vertical='top')
    for c in row[7:10]: c.fill=PatternFill('solid',fgColor='FFF2CC')
for i,w in enumerate([5,9,14,30,100,40,18,50,18,12,30],1): ws.column_dimensions[get_column_letter(i)].width=w
dv=DataValidation(type='list',formula1='"Открыт,В работе,Решён,Отложен"',allow_blank=True); ws.add_data_validation(dv); dv.add(f'J2:J{len(Q)+1}')
ws.freeze_panes='E2'; ws.auto_filter.ref=f'A1:K{len(Q)+1}'
ws2=wb.create_sheet('Как пользоваться')
for line in ['Реестр открытых вопросов по унификации договоров «Ауыл-Аманат».',
 'Каждая строка — вопрос, который анализ зафиксировал, но не решает (по правилам задачи правильный вариант не выбирается).',
 'Жёлтые столбцы заполняет команда: «Решение», «Ответственный», «Статус».',
 'Столбец «Кто решает» — только предложение; распределение определяет руководитель.',
 'Ссылки ведут на файлы в _work/analysis/. Полные формулировки и цитаты — в 02_сравнение_<тип>.xlsx.',
 'Файл пересобирается скриптом tmp/build_questions.py. Заполненные командой ячейки при пересборке не сохраняются — перед пересборкой сохраните копию.']:
    ws2.append([line])
ws2.column_dimensions['A'].width=130
wb.save('../02_вопросы_на_решение.xlsx'); print('questions',len(Q))
